+                    assert!(parser.native_raw.is_some());
+                    while parser.next_event().unwrap().is_some() {}
+                } else {
+                    assert!(parser.next_event().is_err());
+                    assert_eq!(parser.current_raw(), Some(text.as_str()));
+                }
