+            .shared_parameter_state()
+            .unwrap()
+            .read
+            .store(true, Ordering::Relaxed);
+        assert!(parser.native_raw.is_some());
+        assert_eq!(parser.current_raw(), Some("text"));
+        assert!(matches!(
+            parser.finish_foreign_dtd().unwrap().kind,
+            EventKind::NotStandalone
+        ));
